SourceCode.Declaration:
/// <summary>
/// Extension class for the "Order Down" button control in the Unit of Measure Conversion Edit or Create form.
/// </summary>
[ExtensionOf(formControlStr(UnitOfMeasureConversionEditOrCreate, AVARUMOrderDownButton))]
internal final class AVARUMUnitOfMeasureConversionEditOrCreate_AVARUMOrderDownButtonCtrl_Extension
{
}

Method.Source:
/// <summary>
/// Handles the click event for the "Order Down" button.
/// </summary>
public void clicked()
{
    FormButtonControl buttonUpControl;
    FormRun formRun;
    FormDataSource formDataSource;
    UnitOfMeasureConversion unitOfMeasureConversion;

    next clicked();

    buttonUpControl = Global::any2Object(this) as FormButtonControl;
    formRun = buttonUpControl.formRun();
    formDataSource = formRun.dataSource(formDataSourceStr(UnitOfMeasureConversionEditOrCreate, UnitOfMeasureConversion));
    unitOfMeasureConversion = formDataSource.cursor();
    unitOfMeasureConversion.changeOrder_AVA(false);

    element.isUnitOrderChanged_AVA(true);
}
